def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > DAILY_SALARY * 1.2:
                    dangerous_prev.append(float(bid))

    if not alive:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, 20.0))
        return float(min(budget, 5.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    threat_prev = max(dangerous_prev) if dangerous_prev else highest_prev

    scarcity = supply / float(WATER_REQ)
    severe_need = (hp <= 2) or (no_water >= 2)
    urgent_need = (hp <= 4) or (no_water >= 1)
    abundant = supply >= 24
    tight = supply <= 18

    if severe_need:
        bid = max(48.0, threat_prev + 2.0)
        if tight:
            bid = max(bid, 72.0)
        return float(min(budget, bid))

    if urgent_need:
        if threat_prev >= 120.0:
            bid = 38.0 if not tight else 62.0
        elif threat_prev >= 85.0:
            bid = threat_prev + 2.0 if tight else 44.0
        else:
            bid = max(34.0, threat_prev + 1.5)
        return float(min(budget, bid))

    if abundant:
        if threat_prev >= 120.0:
            bid = 6.0
        elif threat_prev >= 85.0:
            bid = 12.0
        else:
            bid = max(8.0, min(22.0, threat_prev * 0.35 + 3.0))
        return float(min(budget, bid))

    if tight:
        if threat_prev >= 120.0:
            bid = 18.0
        elif threat_prev >= 85.0:
            bid = 26.0
        else:
            bid = max(18.0, min(36.0, threat_prev + 2.0))
    else:
        if threat_prev >= 120.0:
            bid = 10.0
        elif threat_prev >= 85.0:
            bid = 18.0
        else:
            bid = max(12.0, min(28.0, threat_prev * 0.45 + 4.0))

    if day >= 8 and hp >= 6:
        bid *= 0.85

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 85.0

    if my_status['hp'] <= 3:
        target_bid = min(my_status['budget'], DAILY_SALARY * 1.1)
    else:
        target_bid = min(my_status['budget'], max(avg_opp_bid + 2.0, DAILY_SALARY * 0.95))

    return float(target_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.35))

    # Extract yesterday bids from previous_trace for immediate pressure signal
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: when supply is low, competition for the same water is higher.
    # Normalize supply into [0,1]
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / denom
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # If our HP is critical or no-water streak is long, increase bid.
    hp_risk = 0.0
    if my_hp <= 2.0:
        hp_risk = 1.0
    elif my_hp <= 4.0:
        hp_risk = 0.7
    elif my_hp <= 6.0:
        hp_risk = 0.4
    else:
        hp_risk = 0.2

    if my_no_water_days >= 2:
        hp_risk = max(hp_risk, 0.7)

    # Decide aggressiveness based on yesterday max bid pressure.
    # Yesterday top bids were high (Alex/Cindy), so we bid to beat them when pressure is high.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        pressure = 0.7
    elif highest_prev_bid >= DAILY_SALARY * 0.30:
        pressure = 0.45
    else:
        pressure = 0.25

    # Base bid target: mid-high, higher when supply is low.
    # target grows with (hp_risk + pressure) and with low supply.
    low_supply_factor = 1.0 - supply_norm  # 1 when supply=MIN_SUPPLY
    target = DAILY_SALARY * (0.25 + 0.35 * pressure + 0.25 * hp_risk) * (0.75 + 0.35 * low_supply_factor)

    # If our budget is very low, don't chase; bid what we can.
    # If budget is healthy, add a small overbid to capture water under competition.
    budget_frac = my_budget / (DAILY_SALARY + 1e-9)
    if budget_frac < 0.25:
        target = min(target, DAILY_SALARY * 0.25)
    elif budget_frac < 0.6:
        target = min(target, DAILY_SALARY * 0.55)
    else:
        target = target * 1.05

    # Ensure we don't exceed budget and keep non-negative.
    bid = max(0.0, min(my_budget, target))

    # If we are extremely safe (high HP) and supply is high, slightly reduce to conserve budget.
    if my_hp >= 8.0 and supply_norm >= 0.7 and my_no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.45)

    # Small day-based jitter (deterministic) to avoid ties.
    jitter = ((day % 7) - 3) * 0.02 * DAILY_SALARY
    bid = bid + jitter
    if bid < 0.0:
        bid = 0.0

    if bid > my_budget:
        bid = my_budget

    return float(bid)
